command:
/**
 * SVA example: Flask Throw
 * Throws an alchemical flask at every target: the glass shatters and a burst of the chosen
 * element sprays away from the thrower. Pick the element in ELEMENT below.
 *
 * Usage: select the thrower, target one or more tokens, run.
 * Requires: Sargas Visual Automation + JB2A (Patreon). No Sequencer needed.
 */
const SVA = game.modules.get("sargas-visual-automation")?.api;
if (!SVA?.ready) return ui.notifications.error("Sargas Visual Automation is not ready.");

const ELEMENT = "frost"; // "frost" | "poison" | "arcane"
const ELEMENTS = {
  frost: {
    flask: "jb2a.throwable.throw.flask.02.blue",
    shards: ["jb2a.side_impact.part.fast.ice_shard.blue", "jb2a.side_impact.part.slow.snowflake.blue"],
    tint: "#9fd3ff"
  },
  poison: {
    flask: "jb2a.throwable.throw.flask.01.black",
    shards: ["jb2a.side_impact.part.slow.poison.greenyellow", "jb2a.side_impact.part.smoke.greenyellow.01"],
    tint: "#b8ff7a"
  },
  arcane: {
    flask: "jb2a.throwable.throw.flask.02.purple",
    shards: ["jb2a.side_impact.part.slow.star.pinkyellow", "jb2a.side_impact.part.slow.spiral.pinkpurple"],
    tint: "#e3a6ff"
  }
};
const style = ELEMENTS[ELEMENT] ?? ELEMENTS.frost;

const thrower = canvas.tokens.controlled[0] ?? token;
const targets = [...game.user.targets];
if (!thrower) return ui.notifications.warn("Select the throwing token.");
if (!targets.length) return ui.notifications.warn("Target at least one token.");
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/** Adds a side-spray effect at the target, pointing away from the thrower. */
function spray(seq, target, file, scale, { mirror = false, tint = null } = {}) {
  const fx = seq.effect().file(file).atLocation(target).rotateTowards(thrower).rotate(180).scale(scale);
  if (mirror) fx.mirrorY();
  if (tint) fx.tint(tint);
  return fx;
}

const runs = [];
for (const target of targets) {
  const seq = SVA.sequence();
  seq.effect().file(style.flask).atLocation(thrower).stretchTo(target).waitUntilFinished(-150);
  spray(seq, target, "jb2a.explosion.side_fracture.flask.02", 0.5);
  spray(seq, target, style.shards[0], 0.45);
  spray(seq, target, style.shards[1], 0.35, { mirror: true });
  spray(seq, target, "jb2a.smoke.puff.side.02.white", 0.6, {
    mirror: true,
    tint: style.tint
  });
  seq
    .effect()
    .file("jb2a.smoke.puff.ring.01.white")
    .atLocation(target)
    .scale(0.4)
    .rotate(Math.random() * 360)
    .tint(style.tint);
  runs.push(seq.play());
  await sleep(700);
}
await Promise.all(runs);
